// Package probe checks whether nodes are alive by opening TCP connections to them.
//
// A probe succeeds when the connection is established or refused (ECONNREFUSED):
// a RST proves the node kernel received the SYN. Timeouts and all other errors,
// such as EHOSTUNREACH generated by the local kernel or a router, are failures.
// Each target is probed serially: the next probe starts Interval after the
// previous one finishes.
package probe

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/netip"
	"strconv"
	"sync"
	"syscall"
	"time"
)

type Config struct {
	Port             int
	Timeout          time.Duration
	Interval         time.Duration
	FailureThreshold int
}

func DefaultConfig() Config {
	return Config{Port: 10250, Timeout: 2 * time.Second, Interval: 5 * time.Second, FailureThreshold: 3}
}

func (c Config) Validate() error {
	if c.Port <= 0 || c.Port > 65535 {
		return fmt.Errorf("invalid probe port %d", c.Port)
	}
	if c.Timeout <= 0 || c.Interval <= 0 {
		return errors.New("probe timeout and interval must be positive")
	}
	if c.FailureThreshold < 1 {
		return errors.New("probe failureThreshold must be at least 1")
	}
	return nil
}

// DialFunc opens a connection and returns nil when the target is alive.
type DialFunc func(ctx context.Context, addr string) error

// Once probes addr once and returns nil when the node is alive.
func Once(ctx context.Context, addr string) error {
	var d net.Dialer
	conn, err := d.DialContext(ctx, "tcp", addr)
	if err == nil {
		_ = conn.Close()
	}
	return classify(err)
}

// classify maps a dial error to nil when it proves the node is alive.
func classify(err error) error {
	if err == nil || errors.Is(err, syscall.ECONNREFUSED) {
		return nil
	}
	return err
}

// Result is the probe state of one target.
type Result struct {
	Addr string
	// Probed is false until the first probe finishes.
	Probed bool
	// ConsecutiveFailures is reset to 0 by a successful probe.
	ConsecutiveFailures int
	LastError           string
	LastProbeTime       time.Time
	threshold           int
}

// Reachable is true when the last probe succeeded.
func (r Result) Reachable() bool { return r.Probed && r.ConsecutiveFailures == 0 }

// Failed is true when the failure threshold is reached.
func (r Result) Failed() bool { return r.ConsecutiveFailures >= r.threshold }

func (r Result) Message() string {
	switch {
	case !r.Probed:
		return fmt.Sprintf("probe to %s not finished yet", r.Addr)
	case r.ConsecutiveFailures == 0:
		return fmt.Sprintf("probe to %s succeeded", r.Addr)
	default:
		return fmt.Sprintf("%d/%d probes to %s failed: %s", r.ConsecutiveFailures, r.threshold, r.Addr, r.LastError)
	}
}

type target struct {
	addr   string
	cancel context.CancelFunc
	done   chan struct{}
	result Result
}

// Prober probes a dynamic set of targets, one goroutine per target.
type Prober struct {
	cfg      Config
	dial     DialFunc
	onChange func(name string)

	mu      sync.Mutex
	targets map[string]*target
}

// New creates a Prober. onChange, if set, is called after a probe changes the
// result of a target (first result, success/failure, failure count).
func New(cfg Config, dial DialFunc, onChange func(name string)) *Prober {
	if dial == nil {
		dial = Once
	}
	return &Prober{cfg: cfg, dial: dial, onChange: onChange, targets: map[string]*target{}}
}

// SetTargets sets the targets to probe, keyed by node name. Targets that are
// removed or whose IP changed are stopped; new ones start with an empty result.
func (p *Prober) SetTargets(ips map[string]netip.Addr) {
	p.mu.Lock()
	var stopped []*target
	for name, t := range p.targets {
		if ip, ok := ips[name]; !ok || p.addr(ip) != t.addr {
			t.cancel()
			stopped = append(stopped, t)
			delete(p.targets, name)
		}
	}
	for name, ip := range ips {
		if _, ok := p.targets[name]; ok {
			continue
		}
		ctx, cancel := context.WithCancel(context.Background())
		t := &target{addr: p.addr(ip), cancel: cancel, done: make(chan struct{})}
		t.result = Result{Addr: t.addr, threshold: p.cfg.FailureThreshold}
		p.targets[name] = t
		go p.run(ctx, name, t)
	}
	p.mu.Unlock()
	for _, t := range stopped {
		<-t.done
	}
}

// Get returns the result of a target.
func (p *Prober) Get(name string) (Result, bool) {
	p.mu.Lock()
	defer p.mu.Unlock()
	t, ok := p.targets[name]
	if !ok {
		return Result{}, false
	}
	return t.result, true
}

// Stop stops all targets.
func (p *Prober) Stop() { p.SetTargets(nil) }

func (p *Prober) addr(ip netip.Addr) string {
	return net.JoinHostPort(ip.String(), strconv.Itoa(p.cfg.Port))
}

func (p *Prober) run(ctx context.Context, name string, t *target) {
	defer close(t.done)
	for {
		dctx, cancel := context.WithTimeout(ctx, p.cfg.Timeout)
		err := p.dial(dctx, t.addr)
		cancel()
		if ctx.Err() != nil {
			return
		}

		p.mu.Lock()
		prev := t.result
		r := prev
		r.Probed = true
		r.LastProbeTime = time.Now()
		if err == nil {
			r.ConsecutiveFailures = 0
			r.LastError = ""
		} else {
			r.ConsecutiveFailures++
			r.LastError = err.Error()
		}
		t.result = r
		p.mu.Unlock()

		changed := !prev.Probed || prev.ConsecutiveFailures != r.ConsecutiveFailures
		if changed && p.onChange != nil {
			p.onChange(name)
		}

		select {
		case <-ctx.Done():
			return
		case <-time.After(p.cfg.Interval):
		}
	}
}
